const DECLARATION: &str = "pub static SPREAD_BASELINE_CTRADER: &[(&str, &str, &str, bool, u32, [f64; 24], f64, f64, f64, [f64; 24])] = &[";

pub(super) fn table(symbols: &[&str]) -> String {
    crate::ctrader::test_logging();
    let rows = symbols.iter().map(|symbol| format!(
        "    (\"ctrader-demo\", \"ctrader:demo:{symbol}\", \"ny\", true, 0, [0.0; 24], 1.0, 0.5, 2.0, [0.00001; 24]),\n"
    )).collect::<String>();
    let endpoint = ctrader_api::Environment::Demo.endpoint();
    format!(
        "// @generated by bake-ctrader. Identity={{\"profile\":\"demo\",\"environment\":\"demo\",\"endpoint\":\"{endpoint}\",\"account_id\":42,\"broker\":\"Example\",\"login\":123}}.\n// Genuine paired M1 ticks through candle-cache, UTC 2026-07-01 00:00:00 UTC through 2026-10-01 00:00:00 UTC.\n#[rustfmt::skip]\n#[allow(clippy::type_complexity)]\n{DECLARATION}\n{rows}];\n"
    )
}
